const rows = $items('Read Jobs', 0).map((item) => item.json);
if (!rows.length) {
  throw new Error('Pick Jobs: Read Jobs returned 0 rows');
}
const TECH = new Set([
  'Applied AI', 'AI Product', 'AI Solutions', 'Growth Engineering', 'Digital Operations', 'Marketing Technology',
]);
const MKT = new Set([
  'Growth Marketing', 'Performance Marketing Leadership', 'Analytics & CRO', 'Product-led Growth', 'Revenue Systems',
]);
const policy = $('Check Apply Policy').first().json;
const ATTEMPT_CAP = Math.max(0, Number(policy.dailyPickLimit ?? policy.maxAttempts ?? 20));
const TARGET_MKT = Math.round(ATTEMPT_CAP * 0.35);
const TARGET_TECH = ATTEMPT_CAP - TARGET_MKT;
// Admin SSOT: Google Sheet tab "Exclude Companies" (Company column).
const excludedCompanies = (() => {
  try {
    return $('Load Exclude Companies').all()
      .map((item) => String(item.json.Company || item.json.company || '').trim())
      .filter(Boolean);
  } catch (e) {
    return [];
  }
})();

function side(row) {
  const c = String(row.Category || '').trim();
  if (MKT.has(c)) return 'marketing';
  if (TECH.has(c)) return 'tech';
  return 'other';
}
function score(row) {
  const n = Number(String(row['Match Score'] || '').replace(/[^\d.]/g, ''));
  return Number.isFinite(n) ? n : 0;
}
function okUrl(url) {
  const u = String(url || '').trim();
  if (!/^https?:\/\//i.test(u)) return false;
  const host = u.replace(/^https?:\/\//i, '').split('/')[0];
  if (!host) return false;
  if (u.toLowerCase().includes('/jobs/stampli/') && u.toLowerCase().includes('0b.273')) return false;
  if (/^https:\/\/apply\.workable\.com\/comeet\//i.test(u)) return false;
  return true;
}
function normalizeCompanyKey(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFKC')
    .replace(/[\s_\-./]+/g, '')
    .replace(/[^\p{L}\p{N}]+/gu, '');
}
function isExcludedCompany(company) {
  const key = normalizeCompanyKey(company);
  if (!key) return false;
  for (const excluded of excludedCompanies) {
    const needle = normalizeCompanyKey(excluded);
    if (!needle) continue;
    if (key === needle || key.includes(needle)) return true;
  }
  return false;
}
function applyTier(row) {
  const u = String(row['Job URL'] || '');
  if (/linkedin\.com|gotfriends\.co\.il|dialog\.co\.il|drushim\.co\.il|sqlink\.com|jobmaster\.co\.il|comblack\.co\.il/i.test(u)) return 0;
  return 1;
}
function sortRows(list) {
  return list.sort((a, b) => score(b) - score(a) || String(b['Found Date'] || '').localeCompare(String(a['Found Date'] || '')));
}

const seenUrl = new Set();
const jobs = [];
for (const row of rows) {
  const status = String(row.Status || '').trim();
  const retryUpload = status === 'Review' && String(row.Notes || '').includes('cv_upload_failed');
  if ((status !== 'New' && !retryUpload) || !okUrl(row['Job URL'])) continue;
  if (isExcludedCompany(row.Company)) continue;
  const url = String(row['Job URL'] || '');
  if (seenUrl.has(url)) continue;
  seenUrl.add(url);
  jobs.push(row);
}

const tech = sortRows(jobs.filter((r) => side(r) === 'tech'));
const mkt = sortRows(jobs.filter((r) => side(r) === 'marketing'));
const other = sortRows(jobs.filter((r) => side(r) === 'other'));

const pickedMkt = mkt.slice(0, TARGET_MKT);
const pickedTech = tech.slice(0, TARGET_TECH);
let picked = [...pickedMkt, ...pickedTech];
const pickedUrls = new Set(picked.map((r) => String(r['Job URL'] || '')));

const backfill = sortRows([
  ...tech.slice(TARGET_TECH),
  ...mkt.slice(TARGET_MKT),
  ...other,
]).filter((r) => !pickedUrls.has(String(r['Job URL'] || '')));

for (const row of backfill) {
  if (picked.length >= ATTEMPT_CAP) break;
  picked.push(row);
}

picked = sortRows([...picked]).slice(0, ATTEMPT_CAP);
return picked.map((row) => ({ json: row }));

const src = $('One Job').item.json;
const res = $json || {};
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Jerusalem' });
if (res.status === 'budget_reached') {
  return [{
    json: {
      row_number: src.row_number,
      company: src.Company,
      role: src.Role,
      Status: 'New',
      'Applied Date': src['Applied Date'] || '',
      Notes: src.Notes || '',
      'Job URL': src['Job URL'],
      workerStatus: 'budget_reached',
    },
  }];
}
if (res.status === 'quota_reached') {
  return [{
    json: {
      row_number: src.row_number,
      company: src.Company,
      role: src.Role,
      Status: 'New',
      'Applied Date': src['Applied Date'] || '',
      Notes: src.Notes || '',
      'Job URL': src['Job URL'],
      workerStatus: 'quota_reached',
    },
  }];
}
const labels = { applied: 'Applied', closed: 'Closed', not_relevant: 'Not Relevant', no_suitable_replacement: 'Not Relevant', review: 'Review', failed: 'Review', invalid_url: 'Review', confirmation_not_detected: 'Review', already_submitted: 'Review', location_ineligible: 'Not Relevant', manual_required: 'Manual' };
const status = res.blocker === 'captcha' ? 'Manual' : (labels[res.status] || 'Review');
const notes = [res.notes || res.message || res.error || 'Worker returned no notes.', res.attemptId ? `attempt_id=${res.attemptId}` : ''].filter(Boolean).join('\n');
return [{
  json: {
    row_number: src.row_number,
    company: src.Company,
    role: src.Role,
    Status: status,
    'Applied Date': status === 'Applied' ? (String(res.appliedAt || '').slice(0, 10) || today) : (src['Applied Date'] || ''),
    Notes: notes,
    'Job URL': res.canonicalJobUrl || src['Job URL'],
    workerStatus: res.status || 'failed',
  },
}];

const job = $('One Job').item.json;
const rowNumber = job.row_number;
if (rowNumber === undefined || rowNumber === null || rowNumber === '') {
  throw new Error(`Missing row_number for job ${job.Company || '?'} — ${job.Role || job['Job URL'] || 'no url'}`);
}
return [{
  json: {
    ...job,
    row_number: rowNumber,
    quota: $json,
  },
}];

const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const DEBOUNCE_MS = 2 * 60 * 1000; // prevent double webhook / overlapping cron within 2 min
if (staticData.applyRunStartedAt && now - staticData.applyRunStartedAt < DEBOUNCE_MS) {
  throw new Error('Apply workflow started moments ago (debounce). Retry in 2 minutes.');
}
staticData.applyRunStartedAt = now;
return $input.all();

const companies = $('Load Exclude Companies').all()
  .map((item) => String(item.json.Company || item.json.company || '').trim())
  .filter(Boolean);
return [{ json: { companies, excludeCount: companies.length } }];

const staticData = $getWorkflowStaticData('global');
const RULE_VERSION = 1;
if (staticData.jobSheetManualHighlightRuleV === RULE_VERSION) {
  return [{ json: { skipped: true } }];
}
staticData.jobSheetManualHighlightRuleV = RULE_VERSION;
return [{ json: { skipped: false, spreadsheetId: '1fxnXLQndeiw7xT1r4NWwO01J8rOMY5J2zQcjHm3HqnQ', sheetId: 175958148 } }];

